// Shared field-mapping logic for filling an uploaded PDF bill template with a
// member's real bill data. Used by BOTH the actual bill-download route
// (app/api/bills/download/route.js) and the admin's "sample preview" route
// (app/api/bill-template/preview-fill/route.js) so the preview the admin
// confirms is generated by the exact same code path that produces real bills
// — no drift between what's previewed and what members actually receive.
function formatMoney(value) {
  return `Rs. ${Number(value || 0).toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}
function formatDateForPdf(dateValue) {
  return new Date(dateValue).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}
// Builds { items, paymentDetails, formFieldData } for FlexiblePDFGenerator.generateBill
export function buildPdfFillData({ bill, society, member }) {
  const currentBillTotal = Number(bill.currentBillTotal ?? bill.totalAmount ?? 0);
  const previousBalance = Number(bill.previousBalance || 0);
  const interestAmount = Number(bill.interestAmount || 0);
  // previousBalance already includes carried interest (openingInterest), and
  // interestAmount = openingInterest + currentInterest — summing both would
  // double-count the carried interest. Only this month's NEW interest gets
  // added on top of previousBalance (mirrors lib/bill-renderer.js).
  const currentInterestOnly = Number(bill.currentInterest ?? interestAmount);
  const totalPayable = +(currentBillTotal + previousBalance + currentInterestOnly).toFixed(2);
  const items = Object.entries(bill.charges || {}).map(([description, amount]) => ({
    description,
    quantity: 1,
    rate: Number(amount || 0),
    amount: Number(amount || 0),
  }));
  const paymentDetails = [
    `Previous dues: ${formatMoney(previousBalance)}`,
    `Interest: ${formatMoney(interestAmount)}`,
    `Total payable: ${formatMoney(totalPayable)}`,
  ].join(" | ");
  const formFieldData = {
    "Company name": society.name || "",
    Address: society.address || "",
    "GST number": society.gstNumber || "N/A",
    "Invoice number": bill.billPeriodId || String(bill._id),
    "Invoice date_af_date": formatDateForPdf(bill.generatedAt || bill.createdAt),
    "Bill date_af_date": formatDateForPdf(bill.generatedAt || bill.createdAt),
    "Due date_af_date": formatDateForPdf(bill.dueDate || new Date()),
    "Customer name": member?.ownerName || "",
    "Customer address": `${member?.wing || ""}-${member?.flatNo || ""}`,
    "Customer phone": member?.contactNumber || "",
    "Customer GST number": "N/A",
    "Sub Total": Number(currentBillTotal || 0).toFixed(2),
    Discount: "0",
    "Tax Rate": "0",
    "Tax value": Number(bill.serviceTax || 0).toFixed(2),
    Shipping: "0",
    "Previous dues": Number(previousBalance || 0).toFixed(2),
    "Grand total": Number(totalPayable || 0).toFixed(2),
    "Account holder name": society.bankDetails?.accountHolderName || "",
    "Account number": society.bankDetails?.accountNumber || "",
    "Bank name": society.bankDetails?.bankName || "",
    "IFSC Code": society.bankDetails?.ifscCode || "",
  };
  items.slice(0, 6).forEach((item, index) => {
    const productNum = index + 1;
    formFieldData[`Product #${productNum}`] = item.description || "";
    formFieldData[`Product #${productNum} amount`] = Number(item.amount || 0).toFixed(2);
    formFieldData[`Product #${productNum} Rate`] = Number(item.rate || 0).toFixed(2);
    formFieldData[`Qty #${productNum}`] = String(item.quantity || 1);
    formFieldData[`HSN code #${productNum}`] = item.hsnCode || "";
  });
  return {
    items,
    paymentDetails,
    formFieldData,
    currentBillTotal,
    previousBalance,
    interestAmount,
    totalPayable,
  };
}
// Flat overlay field object (companyName/invoiceNumber/... — the exact keys
// FlexiblePDFGenerator's overlay draw path + OVERLAY_FIELD_KEYS below use).
// Shared by the PDF overlay path (generateBill), the uploaded-image path
// (generateImageOverlay), and both admin preview routes — one place builds
// this shape so bill PDF and bill image templates can never drift.
export function buildOverlayBillData({ bill, society, member }) {
  const { items, paymentDetails, currentBillTotal, totalPayable } = buildPdfFillData({
    bill,
    society,
    member,
  });
  return {
    companyName: society.name || "",
    invoiceNumber: bill.billPeriodId || String(bill._id),
    customerName: member?.ownerName || "",
    customerAddress: `${member?.wing || ""}-${member?.flatNo || ""}`,
    customerPhone: member?.contactNumber || "",
    billDate: bill.generatedAt || bill.createdAt || new Date(),
    dueDate: bill.dueDate || new Date(),
    items,
    subtotal: currentBillTotal,
    tax: bill.serviceTax || 0,
    total: totalPayable,
    paymentDetails,
  };
}
// Overlay field keys the non-form-field (image-scan) PDF path draws at fixed
// positions (see lib/pdf-fields-config.js). Exposed so the admin UI can offer
// exactly the set of keys that are actually wired into generation — nothing
// the admin configures here can silently do nothing.
export const OVERLAY_FIELD_KEYS = [
  { key: "companyName", label: "Society name" },
  { key: "invoiceNumber", label: "Invoice / bill number" },
  { key: "customerName", label: "Member name" },
  { key: "customerAddress", label: "Flat / address" },
  { key: "customerPhone", label: "Member phone" },
  { key: "billDate", label: "Bill date" },
  { key: "dueDate", label: "Due date" },
  { key: "subtotal", label: "Subtotal" },
  { key: "tax", label: "Tax" },
  { key: "total", label: "Total payable" },
  { key: "paymentDetails", label: "Payment details line" },
];
